import{_ as e,o as i,c as n,a6 as r}from"./chunks/framework.DycQjAfF.js";const m=JSON.parse('{"title":"SOP Pengeluaran Barang","description":"Langkah mengeluarkan material berdasarkan reservasi di ERP/WMS, mulai dari persetujuan dan verifikasi NIP sampai barang diserahkan.","frontmatter":{"title":"SOP Pengeluaran Barang","description":"Langkah mengeluarkan material berdasarkan reservasi di ERP/WMS, mulai dari persetujuan dan verifikasi NIP sampai barang diserahkan.","status":"ditinjau","dasar":"Instruksi Kerja Pelayanan Barang Gudang Teknik dan alur barang keluar Gudang Teknik","nomor_dokumen":null,"versi":0.3,"pemilik":"Gudang Teknik","pengesah":null,"diperbarui":"2026-10-20T00:00:00.000Z","kategori":"SOP","sumber":["ik-gudang-teknik","ppt-gudang-teknik","catatan-alur"],"kata_kunci":["SOP","pengeluaran barang","barang keluar","pelayanan barang","reservasi","good issue","ERP","WMS","material reservation list","NIP","ID card","stock keeper","foreman","supervisor","rak reservasi","3 hari","material bekas","kartu stok","FIFO","tukar barang"]},"headers":[],"relativePath":"sop/pengeluaran-barang.md","filePath":"sop/pengeluaran-barang.md"}'),t={name:"sop/pengeluaran-barang.md"};function s(l,a,u,d,k,g){return i(),n("div",null,[...a[0]||(a[0]=[r('<h1 id="sop-pengeluaran-barang" tabindex="-1">SOP Pengeluaran Barang <a class="header-anchor" href="#sop-pengeluaran-barang" aria-label="Permalink to &quot;SOP Pengeluaran Barang&quot;">​</a></h1><p class="lead">Dipakai setiap kali divisi lain mengambil material dari gudang. Pengeluaran barang di Gudang Teknik selalu berdasarkan reservasi (<em>good issue to reservation</em>). Isinya diringkas dari Instruksi Kerja Pelayanan Barang Gudang Teknik.</p><h2 id="tujuan" tabindex="-1">Tujuan <a class="header-anchor" href="#tujuan" aria-label="Permalink to &quot;Tujuan&quot;">​</a></h2><p>Menjadi pedoman petugas Warehouse dalam mengeluarkan material berdasarkan reservasi, supaya barang yang diserahkan benar dan setiap pengeluaran tercatat, baik di sistem maupun di kartu stok.</p><h2 id="berlaku-untuk" tabindex="-1">Berlaku untuk <a class="header-anchor" href="#berlaku-untuk" aria-label="Permalink to &quot;Berlaku untuk&quot;">​</a></h2><p>Seluruh proses reservasi dan pengeluaran material, di sistem ERP/WMS (sesuai nomor reservasi) maupun secara fisik: mulai dari reservasi, persetujuan, verifikasi NIP pengambil, sampai material diserahkan kepada penerima (<em>recipient</em>).</p><h2 id="peran" tabindex="-1">Peran <a class="header-anchor" href="#peran" aria-label="Permalink to &quot;Peran&quot;">​</a></h2><table class="tabel-tumpuk" tabindex="0"><thead><tr><th>Peran</th><th>Tanggung jawab</th></tr></thead><tbody><tr><td data-label="Peran"><strong>User (divisi pemesan)</strong></td><td data-label="Tanggung jawab">Mengecek ketersediaan material dan membuat reservasi di ERP/WMS.</td></tr><tr><td data-label="Peran"><strong>Foreman/Supervisor divisi pemesan</strong></td><td data-label="Tanggung jawab">Menunjuk karyawan yang ditugaskan mengambil barang, dan menyetujui reservasi di sistem.</td></tr><tr><td data-label="Peran"><strong>Stock Keeper (petugas Warehouse)</strong></td><td data-label="Tanggung jawab">Mencocokkan identitas pengambil, jenis, dan jumlah material yang diserahkan, serta meminta material bekas atau rusak.</td></tr></tbody></table><h2 id="yang-perlu-disiapkan" tabindex="-1">Yang perlu disiapkan <a class="header-anchor" href="#yang-perlu-disiapkan" aria-label="Permalink to &quot;Yang perlu disiapkan&quot;">​</a></h2><ul><li>Komputer, printer, dan sistem ERP/WMS.</li><li>Kartu stok di rak.</li><li>APD sesuai arahan pembimbing.</li></ul><h2 id="langkah-langkah" tabindex="-1">Langkah-langkah <a class="header-anchor" href="#langkah-langkah" aria-label="Permalink to &quot;Langkah-langkah&quot;">​</a></h2><h3 id="di-sisi-divisi-pemesan" tabindex="-1">Di sisi divisi pemesan <a class="header-anchor" href="#di-sisi-divisi-pemesan" aria-label="Permalink to &quot;Di sisi divisi pemesan&quot;">​</a></h3><ol><li><strong>Cek ketersediaan material</strong> di ERP/WMS.</li><li><strong>Buat reservasi</strong> jika material tersedia, dengan mengisi: <ul><li>nomor material yang dibutuhkan,</li><li>jumlah (<em>quantity</em>) sesuai kebutuhan,</li><li>NIP (Nomor Induk Pegawai) karyawan yang ditugaskan mengambil barang.</li></ul></li><li><strong>Reservasi disetujui</strong> di sistem, minimal oleh Foreman atau Supervisor divisi tersebut.</li></ol><h3 id="di-gudang-teknik" tabindex="-1">Di Gudang Teknik <a class="header-anchor" href="#di-gudang-teknik" aria-label="Permalink to &quot;Di Gudang Teknik&quot;">​</a></h3><ol start="4"><li><strong>Cek Material Reservation List</strong> di ERP/WMS: reservasi yang sudah disetujui, beserta NIP pengambilnya.</li><li><strong>Buka nomor reservasi dan cocokkan dengan stok.</strong><ul><li>Kalau stok ada, stok langsung dipotong di sistem.</li><li>Kalau stok sudah habis, misalnya sudah direservasi user lain, item tersebut dibatalkan atau dicoret.</li></ul></li><li><strong>Cetak reservasi dan siapkan material</strong> sesuai jenis dan jumlahnya. Ambil barang yang masuk lebih dulu (FIFO), lalu potong stoknya di kartu stok.</li><li><strong>Taruh material di rak reservasi.</strong> Batas waktu pengambilan adalah <strong>3 hari</strong>. Kalau lewat dari itu dan material tidak jadi dipakai, reservasi dianggap batal dan material dikembalikan ke stok.</li><li><strong>Verifikasi pengambil.</strong> Saat karyawan datang, cocokkan NIP di reservasi dengan ID card pengambil. Minta juga material bekas atau rusak yang diganti, jika ada.</li><li><strong>Serahkan material</strong> kalau hasil verifikasi cocok. Minta karyawan mengecek barangnya. Kalau tidak sesuai orderan, terima kembali barangnya dan tukar dengan yang sesuai.</li><li><strong>Perbarui stock level</strong> di kartu stok.</li></ol><p>Flowchart-nya ada di <a href="/WareHouse/alur-kerja/barang-keluar">Alur Barang Keluar</a>.</p><h2 id="setelah-melayani" tabindex="-1">Setelah melayani <a class="header-anchor" href="#setelah-melayani" aria-label="Permalink to &quot;Setelah melayani&quot;">​</a></h2><p>Setiap hari, tim gudang menghitung jumlah fisik barang yang keluar dan masuk, lalu membandingkannya dengan saldo di sistem atau kartu stok. Kalau ada selisih, cari akar masalahnya, misalnya salah input, barang tidak ditaruh di tempatnya, atau barang yang diambil tidak sesuai. Caranya ada di <a href="./stock-opname">SOP Stock Opname</a>.</p><h2 id="cek-sebelum-selesai" tabindex="-1">Cek sebelum selesai <a class="header-anchor" href="#cek-sebelum-selesai" aria-label="Permalink to &quot;Cek sebelum selesai&quot;">​</a></h2><ul class="daftar-periksa"><li>Reservasi sudah disetujui Foreman/Supervisor divisi pemesan.</li><li>Stok sudah dipotong di sistem dan di kartu stok.</li><li>Kode dan spesifikasi barang sesuai reservasi.</li><li>NIP pengambil cocok dengan ID card.</li><li>Material bekas atau rusak sudah diminta, jika ada.</li><li>Barang sudah dicek karyawan dan dinyatakan sesuai.</li><li>Barang di rak reservasi yang lewat 3 hari sudah dikembalikan ke stok.</li></ul><h2 id="perhatian-keselamatan" tabindex="-1">Perhatian keselamatan <a class="header-anchor" href="#perhatian-keselamatan" aria-label="Permalink to &quot;Perhatian keselamatan&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Saat mengambil barang</p><ul><li>Pakai tangga atau alat bantu untuk rak tinggi. Jangan memanjat rak.</li><li>Angkat barang dengan menekuk lutut dan punggung tetap lurus. Minta bantuan untuk barang berat atau panjang.</li><li>Pakai sarung tangan untuk barang bersudut tajam.</li></ul></div>',22)])])}const h=e(t,[["render",s]]);export{m as __pageData,h as default};
